"""Validators V7-V9.

Each validator takes a list of entries and returns a list of problem
strings. An empty list means the check passed.
"""

from collections import Counter

RELIABILITY_MIN = 0
RELIABILITY_MAX = 100


def _capacity_problem(entry):
    """Return a problem string if max_units exceeds capacity, else None."""
    if entry["max_units"] > entry["capacity"]:
        return (
            f"warehouse {entry['wh']}: max_units {entry['max_units']} "
            f"exceeds capacity {entry['capacity']}"
        )
    return None


def validate_capacity_respected(entries):
    """V7: every warehouse's max_units stayed within its capacity."""
    problems = (_capacity_problem(entry) for entry in entries)
    return [problem for problem in problems if problem is not None]


def _missing_notifications(entry):
    """Return the expired items that were not matched by a notification.

    Items are compared as (sku, wh, qty) tuples, counting duplicates.
    """
    expired = Counter(tuple(item) for item in entry["expired"])
    notified = Counter(tuple(item) for item in entry["notified"])
    return expired - notified


def validate_expiries_notified(entries):
    """V8: every expired item was notified."""
    problems = []
    for entry in entries:
        for item, count in sorted(_missing_notifications(entry).items()):
            problems.append(
                f"expired item {item} not notified (missing {count})"
            )
    return problems


def _reliability_problem(entry):
    """Return a problem string if reliability is out of range, else None."""
    reliability = entry["reliability"]
    if not RELIABILITY_MIN <= reliability <= RELIABILITY_MAX:
        return (
            f"supplier {entry['supplier']}: reliability {reliability} "
            f"outside [{RELIABILITY_MIN}, {RELIABILITY_MAX}]"
        )
    return None


def validate_supplier_reliability(entries):
    """V9: every supplier's reliability stayed within the allowed range."""
    problems = (_reliability_problem(entry) for entry in entries)
    return [problem for problem in problems if problem is not None]
