import unittest

from validators_later import (
    validate_capacity_respected,
    validate_expiries_notified,
    validate_supplier_reliability,
)


class CapacityRespectedTests(unittest.TestCase):
    def test_empty_input_passes(self):
        self.assertEqual(validate_capacity_respected([]), [])

    def test_within_capacity_passes(self):
        entries = [{"wh": "A", "capacity": 10, "max_units": 10}]
        self.assertEqual(validate_capacity_respected(entries), [])

    def test_over_capacity_reported(self):
        entries = [
            {"wh": "A", "capacity": 10, "max_units": 11},
            {"wh": "B", "capacity": 5, "max_units": 3},
        ]
        problems = validate_capacity_respected(entries)
        self.assertEqual(len(problems), 1)
        self.assertIn("warehouse A", problems[0])


class ExpiriesNotifiedTests(unittest.TestCase):
    def test_empty_input_passes(self):
        self.assertEqual(validate_expiries_notified([]), [])

    def test_all_notified_passes(self):
        entries = [
            {
                "expired": [["sku1", "A", 2]],
                "notified": [["sku1", "A", 2]],
            }
        ]
        self.assertEqual(validate_expiries_notified(entries), [])

    def test_missing_notification_reported(self):
        entries = [
            {
                "expired": [["sku1", "A", 2], ["sku2", "B", 1]],
                "notified": [["sku1", "A", 2]],
            }
        ]
        problems = validate_expiries_notified(entries)
        self.assertEqual(len(problems), 1)
        self.assertIn("sku2", problems[0])

    def test_duplicate_expiries_need_duplicate_notifications(self):
        entries = [
            {
                "expired": [["sku1", "A", 2], ["sku1", "A", 2]],
                "notified": [["sku1", "A", 2]],
            }
        ]
        problems = validate_expiries_notified(entries)
        self.assertEqual(len(problems), 1)
        self.assertIn("missing 1", problems[0])

    def test_extra_notifications_are_ignored(self):
        entries = [
            {
                "expired": [],
                "notified": [["sku9", "C", 4]],
            }
        ]
        self.assertEqual(validate_expiries_notified(entries), [])


class SupplierReliabilityTests(unittest.TestCase):
    def test_empty_input_passes(self):
        self.assertEqual(validate_supplier_reliability([]), [])

    def test_bounds_are_inclusive(self):
        entries = [
            {"supplier": "S1", "reliability": 0},
            {"supplier": "S2", "reliability": 100},
        ]
        self.assertEqual(validate_supplier_reliability(entries), [])

    def test_out_of_range_reported(self):
        entries = [
            {"supplier": "S1", "reliability": -1},
            {"supplier": "S2", "reliability": 101},
            {"supplier": "S3", "reliability": 50},
        ]
        problems = validate_supplier_reliability(entries)
        self.assertEqual(len(problems), 2)
        self.assertIn("S1", problems[0])
        self.assertIn("S2", problems[1])


if __name__ == "__main__":
    unittest.main()
